      maxZoom: layer.maxZoom,
      tileMatrixSet: layer.tileMatrixSet,
      extent: layer.extent
        ? Object.fromEntries(Object.entries(layer.extent).map(([k, v]) => [k, Number(v.toFixed(6))]))
        : null,
      attribution: swisstopoAttribution(layer),
      license: SWISSTOPO_LICENSE,
    });
  }
