/** GET /api/health — liveness plus the upstreams this Worker may contact. */
function health(request) {
  return json({
    ok: true,
    version: VERSION,
    runtime: 'cloudflare-workers',
    upstreams: ALLOWLIST.map((r) => r.host),
    endpoints: ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch'],
    placeSources: Object.values(PLACE_SOURCES).map((s) => ({
      id: s.id,
      name: s.name,
      scope: s.scope,
      attribution: s.attribution,
    })),
    time: new Date().toISOString(),
  });
}

/**
 * The two place-search upstreams.
 *
 * swisstopo's SearchServer is the authoritative gazetteer for Switzerland (canton
 * and municipal boundaries, addresses, parcels). It only covers Switzerland — a
 * query for “Amsterdam” answers the fuzzy Swiss hit “Amsteg” — so the worldwide
 * geocoder Photon (OpenStreetMap data, built for search-as-you-type) answers the
 * rest of the world. Both are documented public services, both send CORS `*`, and
 * neither needs a key. Photon's public demo server asks for a reasonable request
 * volume, which is why this route answers from a one-hour edge cache and never
 * fans out: one upstream request per uncached query string.
 */
const PLACE_SOURCES = {
  swisstopo: {
    id: 'swisstopo',
    name: 'swisstopo SearchServer',
    short: 'swisstopo',
    scope: 'Switzerland',
    attribution: '© swisstopo',
    rights: 'Open Government Data (OGD); source reference “©swisstopo” required',
  },
  photon: {
    id: 'photon',
    name: 'OpenStreetMap-Ortsdaten (Photon)',
    short: 'OpenStreetMap',
    scope: 'worldwide',
    attribution: '© OpenStreetMap-Mitwirkende (ODbL 1.0)',
    rights: 'OpenStreetMap data, ODbL 1.0; attribution required',
  },
};

/** German type word for an OpenStreetMap feature, so the badge is readable. */
const OSM_TYPE_DE = {
  city: 'Stadt',
  town: 'Stadt',
  village: 'Dorf',
  hamlet: 'Weiler',
  suburb: 'Quartier',
  neighbourhood: 'Quartier',
  locality: 'Ortschaft',
  state: 'Region',
  province: 'Region',
  county: 'Bezirk',
  district: 'Bezirk',
  region: 'Region',
  country: 'Land',
  administrative: 'Gebiet',
  municipality: 'Gemeinde',
  borough: 'Stadtteil',
  peak: 'Berg',
  mountain_pass: 'Pass',
  water: 'Gewässer',
  river: 'Fluss',
  lake: 'See',
  bay: 'Bucht',
  island: 'Insel',
  station: 'Bahnhof',
  halt: 'Haltestelle',
  aerodrome: 'Flughafen',
  university: 'Universität',
  school: 'Schule',
  museum: 'Museum',
  castle: 'Schloss',
  house: 'Gebäude',
  building: 'Gebäude',
  street: 'Strasse',
  residential: 'Strasse',
  square: 'Platz',
  monument: 'Denkmal',
  church: 'Kirche',
  attraction: 'Sehenswürdigkeit',
};

/** swisstopo SearchServer `type=locations` (unchanged shape, plus the source id). */
async function swisstopoPlaces(q, limit) {
  const target = new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer');
  target.searchParams.set('searchText', q);
  target.searchParams.set('type', 'locations');
  target.searchParams.set('sr', '4326'); // WGS84 lon/lat
  target.searchParams.set('limit', String(limit));
  const res = await upstream(target.toString(), { accept: 'application/json', timeoutMs: 6000 });
  if (!res.ok) throw new Error(`swisstopo SearchServer HTTP ${res.status}`);
  const data = await res.json();
  const results = (data.results || []).map((r) => {
    const a = r.attrs || {};
    const box = (a.geom_st_box2d || 'BOX(0 0,0 0)').match(/BOX\(([-\d.]+) ([-\d.]+),([-\d.]+) ([-\d.]+)\)/);
    return {
      label: String(a.label || '').replace(/<[^>]*>/g, ''),
      origin: a.origin || null,
      lat: typeof a.lat === 'number' ? a.lat : null,
      lon: typeof a.lon === 'number' ? a.lon : null,
      layerBodId: a.layerBodId || null,
      // upstream `zoomlevel` is a bitfield/uint32 for some origins; only pass sane values on
      zoom: Number.isFinite(a.zoomlevel) && a.zoomlevel > 0 && a.zoomlevel <= 20 ? a.zoomlevel : null,
      bbox: box ? { west: Number(box[1]), south: Number(box[2]), east: Number(box[3]), north: Number(box[4]) } : null,
      source: 'swisstopo',
    };
  });
  // “fuzzy” marks a fallback answer: the gazetteer found no exact name and
  // guessed. It stays in the list, but worldwide exact matches belong in front.
  return { results, fuzzy: data.fuzzy === 'true' || data.fuzzy === true };
}

/**
 * Photon (OpenStreetMap) features → the same result shape as the Swiss ones.
 * `extent` is `[west, north, east, south]`, which is the documented order in the
 * Photon API; the bbox is only passed on when all four values are finite.
 */
async function photonPlaces(q, limit, bias) {
  const target = new URL('https://photon.komoot.io/api/');
  target.searchParams.set('q', q);
  target.searchParams.set('limit', String(limit));
  target.searchParams.set('lang', 'de');
  if (bias) {
    target.searchParams.set('lat', String(bias.lat));
    target.searchParams.set('lon', String(bias.lon));
  }
  const res = await upstream(target.toString(), { accept: 'application/json', timeoutMs: 5000 });
  if (!res.ok) throw new Error(`Photon HTTP ${res.status}`);
  const data = await res.json();
  return (data.features || [])
    .map((feature) => {
      const p = feature.properties || {};
      const [lon, lat] = feature.geometry?.coordinates || [];
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
      const parts = [p.name].filter(Boolean).map(String);
      for (const key of ['city', 'state', 'country']) {
        const value = p[key] ? String(p[key]) : '';
        if (value && !parts.some((part) => part.toLowerCase() === value.toLowerCase())) parts.push(value);
      }
      const type = OSM_TYPE_DE[p.osm_value] || OSM_TYPE_DE[p.type] || null;
      const extent = Array.isArray(p.extent) ? p.extent.map(Number) : null;
      const bbox = extent && extent.length === 4 && extent.every(Number.isFinite)
        ? { west: extent[0], north: extent[1], east: extent[2], south: extent[3] }
        : null;
      return {
        label: parts.join(', ') || String(p.name || p.street || ''),
        origin: type ? `OSM · ${type}` : 'OSM',
        lat,
        lon,
        zoom: null,
        bbox: bbox && bbox.west < bbox.east && bbox.south < bbox.north ? bbox : null,
        countryCode: p.countrycode || null,
        osmType: p.osm_type || null,
        osmId: p.osm_id ?? null,
        source: 'photon',
      };
    })
    .filter((place) => place && place.label);
}

const placeKey = (p) => `${String(p.label).toLowerCase()}|${p.lat?.toFixed?.(4) ?? ''}|${p.lon?.toFixed?.(4) ?? ''}`;

/** GET /api/search/places?q=&limit= — swisstopo (Switzerland) + Photon (world). */
async function searchPlaces(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 8), 1), 20);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  // Optional proximity bias (the current map centre), ignored when unusable.
  const lat = Number(url.searchParams.get('lat'));
  const lon = Number(url.searchParams.get('lon'));
  const bias =
    Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) <= 85 && Math.abs(lon) <= 180 ? { lat, lon } : null;

  return cachedJson(
    request,
    ctx,
    async () => {
      const [swiss, world] = await Promise.allSettled([
        swisstopoPlaces(q, limit),
        photonPlaces(q, limit, bias),
      ]);
      const degraded = [];
      if (swiss.status !== 'fulfilled') degraded.push('swisstopo');
      if (world.status !== 'fulfilled') degraded.push('photon');
      if (degraded.length === 2) {
        return {
          results: [],
          count: 0,
          degraded,
          error: 'upstream_unreachable',
          note: 'neither the Swiss gazetteer nor the worldwide geocoder answered',
        };
      }
      const swissResults = swiss.status === 'fulfilled' ? swiss.value.results : [];
      const swissFuzzy = swiss.status === 'fulfilled' ? swiss.value.fuzzy : false;
      const worldResults = world.status === 'fulfilled' ? world.value : [];
      // A fuzzy Swiss answer (no exact Swiss name) must not hide the exact
      // worldwide match: the visitor who typed “Amsterdam” wants the city, not
      // “Amsteg”. Swiss answers keep the front when they are exact, and inside
      // Switzerland they are the better gazetteer anyway.
      const swissFirst = swissResults.length > 0 && !(swissFuzzy && worldResults.length > 0);
      const ordered = swissFirst ? [...swissResults, ...worldResults] : [...worldResults, ...swissResults];
      const seen = new Set();
      const results = [];
      for (const place of ordered) {
        // Inside Switzerland swisstopo already answered: its results are the
        // authoritative ones, so the same place from OpenStreetMap is skipped.
        if (swissResults.length > 0 && place.source === 'photon' && place.countryCode === 'CH') continue;
        const key = placeKey(place);
        if (seen.has(key)) continue;
        seen.add(key);
        results.push(place);
        if (results.length >= limit) break;
      }
      const answered = ['swisstopo', 'photon'].filter((id) => (id === 'swisstopo' ? swissResults.length : worldResults.length));
      const attribution = answered.map((id) => PLACE_SOURCES[id].attribution).join(' · ');
      return {
        results,
        count: results.length,
        fuzzy: swissFuzzy,
        degraded,
        source: answered.map((id) => PLACE_SOURCES[id].short).join(' + ') || 'keine Quelle',
        attribution,
        sources: answered.map((id) => ({
          id,
          name: PLACE_SOURCES[id].name,
          scope: PLACE_SOURCES[id].scope,
