arguments.content:
/**
 * World place search (`/api/search/places`, owner: zurich-maps-0).
 *
 * The route merges two documented public gazetteers: swisstopo's SearchServer
 * (Switzerland only — a query for “Amsterdam” comes back as the fuzzy Swiss hit
 * “Amsteg”) and Photon on OpenStreetMap data (worldwide, built for
 * search-as-you-type). These tests drive the real Worker entry module with a
 * stubbed `fetch`, so they cover the merge, the ordering, the outage behaviour
 * and the cache without touching the network.
 */
import test from 'node:test';
import assert from 'node:assert/strict';

// --- Cloudflare runtime stubs -------------------------------------------------
class MemoryCache {
  constructor() {
    this.store = new Map();
  }
  async match(request) {
    const hit = this.store.get(request.url);
    return hit ? hit.clone() : undefined;
  }
  async put(request, response) {
    this.store.set(request.url, response.clone());
  }
}

const cache = new MemoryCache();
globalThis.caches = { default: cache };

const upstreamCalls = [];
/** url → responder; a plain function answers for every host. */
let responder = {};

globalThis.fetch = async (input, init) => {
  const url = typeof input === 'string' ? input : input.url;
  upstreamCalls.push({ url, init });
  const host = new URL(url).hostname;
  const fn = typeof responder === 'function' ? responder : responder[host];
  if (!fn) return new Response('not found', { status: 404 });
  return fn(url, init);
};

const { default: worker } = await import('../src/worker/index.js');

const env = { ASSETS: { async fetch() { return new Response('{}', { status: 200 }); } } };
const ctx = { waitUntil() {}, passThroughOnException() {} };
const call = (pathname) => worker.fetch(new Request(`https://example.test${pathname}`), env, ctx);

const swisstopoBody = (results, extra = {}) => JSON.stringify({ results, ...extra });
const swissHit = (label, lat, lon, origin = 'gg25') => ({
  attrs: { label, lat, lon, origin, geom_st_box2d: `BOX(${lon - 0.01} ${lat - 0.01},${lon + 0.01} ${lat + 0.01})` },
});

const photonBody = (features) => JSON.stringify({ type: 'FeatureCollection', features });
const photonHit = (name, lon, lat, props = {}) => ({
  type: 'Feature',
  properties: { name, osm_type: 'R', osm_id: 1, osm_value: 'city', type: 'city', countrycode: 'AT', country: 'Österreich', ...props },
  geometry: { type: 'Point', coordinates: [lon, lat] },
});

const JSON_HEADERS = { 'content-type': 'application/json' };

test.beforeEach(() => {
  upstreamCalls.length = 0;
  responder = {};
  cache.store.clear();
});

test('a Swiss query keeps swisstopo first and drops the duplicate Swiss OpenStreetMap hits', async () => {
  responder = {
    'api3.geo.admin.ch': () =>
      new Response(
        swisstopoBody([swissHit('<b>Zürich</b> (ZH) - Stadt', 47.3772, 8.5273)]),
        { status: 200, headers: JSON_HEADERS },
      ),
    'photon.komoot.io': () =>
      new Response(
        photonBody([
          photonHit('Zürich', 8.541, 47.374, { countrycode: 'CH', country: 'Schweiz', state: 'Zürich' }),
          photonHit('Zürich Hauptbahnhof', 8.5393, 47.3781, { osm_value: 'station', countrycode: 'CH' }),
        ]),
        { status: 200, headers: JSON_HEADERS },
      ),
  };
  const res = await call('/api/search/places?q=Z%C3%BCrich&limit=8');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.results[0].label, 'Zürich (ZH) - Stadt', 'the Swiss gazetteer stays in front');
  assert.equal(body.results[0].source, 'swisstopo');
  assert.equal(
    body.results.filter((r) => r.countryCode === 'CH').length,
    1,
    'inside Switzerland swisstopo is the authority: its OpenStreetMap twin is skipped',
  );
  assert.ok(body.results.some((r) => r.source === 'photon' && r.label === 'Zürich Hauptbahnhof'), 'a Swiss detail swisstopo does not know stays reachable');
  assert.equal(body.source, 'swisstopo + OpenStreetMap');
  assert.match(body.attribution, /swisstopo/);
  assert.match(body.attribution, /OpenStreetMap/);
  assert.deepEqual(
    body.sources.map((s) => s.id),
    ['swisstopo', 'photon'],
  );
});

test('a non-Swiss query answers with OpenStreetMap results, not the fuzzy Swiss near-miss', async () => {
  responder = {
    // swisstopo's documented fallback: no exact name, so it guesses (“Amsteg”).
    'api3.geo.admin.ch': () =>
      new Response(swisstopoBody([swissHit('<i>Ort</i> <b>Amsteg</b> (UR)', 46.7727, 8.6672, 'gazetteer')], { fuzzy: 'true' }), {
        status: 200,
        headers: JSON_HEADERS,
      }),
    'photon.komoot.io': () =>
      new Response(
        photonBody([
          photonHit('Amsterdam', 4.8926, 52.3731, { countrycode: 'NL', country: 'Niederlande', state: 'Nordholland', extent: [4.728, 52.431, 5.079, 52.278] }),
        ]),
        { status: 200, headers: JSON_HEADERS },
      ),
  };
  const body = await (await call('/api/search/places?q=Amsterdam&limit=5')).json();
  assert.equal(body.results[0].label, 'Amsterdam, Nordholland, Niederlande');
  assert.equal(body.results[0].source, 'photon');
  assert.deepEqual(body.results[0].bbox, { west: 4.728, north: 52.431, east: 5.079, south: 52.278 }, 'Photon extent [W,N,E,S] becomes a bbox');
  assert.equal(body.results[0].origin, 'OSM · Stadt');
  assert.equal(body.fuzzy, true, 'the fuzzy Swiss answer is still reported as such');
  assert.ok(
    body.results.findIndex((r) => r.source === 'photon') < body.results.findIndex((r) => r.source === 'swisstopo'),
    'an exact worldwide match outranks a fuzzy Swiss guess',
  );
});

test('a place-search outage degrades to the surviving gazetteer instead of failing', async () => {
  responder = {
    'api3.geo.admin.ch': () => new Response(swisstopoBody([swissHit('<b>Bern</b> (BE)', 46.948, 7.4474)]), { status: 200, headers: JSON_HEADERS }),
    'photon.komoot.io': () => new Response('upstream down', { status: 503 }),
  };
  const body = await (await call('/api/search/places?q=Bern')).json();
  assert.equal(body.results.length, 1);
  assert.deepEqual(body.degraded, ['photon']);
  assert.equal(body.source, 'swisstopo', 'the status line names the source that really answered');
  assert.equal(body.attribution, '© swisstopo');
});

test('when neither gazetteer answers the route says so with 502 and caches nothing', async () => {
  responder = {
    'api3.geo.admin.ch': () => new Response('boom', { status: 500 }),
    'photon.komoot.io': () => new Response('boom', { status: 500 }),
  };
  const res = await call('/api/search/places?q=Wien');
  assert.equal(res.status, 502, 'the client must be able to tell “not found” from “upstream unreachable”');
  const body = await res.json();
  assert.equal(body.error, 'upstream_unreachable');
  assert.deepEqual(body.degraded, ['swisstopo', 'photon']);
  assert.equal(cache.store.size, 0, 'a failure is never cached as a success');

  // A second call must reach the upstream again (nothing was cached).
  upstreamCalls.length = 0;
  await call('/api/search/places?q=Wien');
  assert.ok(upstreamCalls.length >= 2, 'the failed answer was not served from cache');
});

test('the second call for the same query is answered from the edge cache', async () => {
  responder = {
    'api3.geo.admin.ch': () => new Response(swisstopoBody([swissHit('<b>Wien</b>', 48.2, 16.37, 'gazetteer')]), { status: 200, headers: JSON_HEADERS }),
    'photon.komoot.io': () => new Response(photonBody([photonHit('Wien', 16.3725, 48.2084)]), { status: 200, headers: JSON_HEADERS }),
  };
  await call('/api/search/places?q=Wien&limit=4');
  const callsAfterFirst = upstreamCalls.length;
  const second = await (await call('/api/search/places?q=Wien&limit=4')).json();
  assert.equal(upstreamCalls.length, callsAfterFirst, 'one upstream request per distinct query, not per keystroke');
  assert.ok(second.results.length > 0);
  assert.equal(second.count, second.results.length);
});

test('the query stays bounded, the bias is passed on only when it is a real coordinate', async () => {
  responder = {
    'api3.geo.admin.ch': () => new Response(swisstopoBody([]), { status: 200, headers: JSON_HEADERS }),
    'photon.komoot.io': () => new Response(photonBody([]), { status: 200, headers: JSON_HEADERS }),
  };
  assert.equal((await call('/api/search/places?q=z')).status, 400);
  assert.equal((await call(`/api/search/places?q=${'x'.repeat(200)}`)).status, 400);
  assert.equal(upstreamCalls.length, 0, 'a rejected query never reaches an upstream');

  await call('/api/search/places?q=Wien&lat=48.2&lon=16.4');
  const photonUrl = new URL(upstreamCalls.find((c) => new URL(c.url).hostname === 'photon.komoot.io').url);
  assert.equal(photonUrl.searchParams.get('lat'), '48.2');
  assert.equal(photonUrl.searchParams.get('lon'), '16.4');
  assert.equal(photonUrl.searchParams.get('lang'), 'de', 'the app is German; Photon localises country names');
  assert.equal(photonUrl.searchParams.get('limit'), '8');

  upstreamCalls.length = 0;
  cache.store.clear();
  await call('/api/search/places?q=Wien&lat=999&lon=abc');
  const plain = new URL(upstreamCalls.find((c) => new URL(c.url).hostname === 'photon.komoot.io').url);
  assert.equal(plain.searchParams.has('lat'), false, 'junk in the URL cannot become an upstream parameter');
  assert.equal(plain.searchParams.has('lon'), false);
});

test('every result carries a source and a readable label, and the limit is respected', async () => {
  responder = {
    'api3.geo.admin.ch': () =>
      new Response(
        swisstopoBody(Array.from({ length: 8 }, (_, i) => swissHit(`Ort ${i}`, 47 + i / 100, 8 + i / 100))),
        { status: 200, headers: JSON_HEADERS },
      ),
    'photon.komoot.io': () =>
      new Response(
        photonBody([
          photonHit('Wien', 16.37, 48.2, { city: undefined, countrycode: 'AT' }),
          photonHit('Wien', 16.37, 48.2, { countrycode: 'AT' }), // exact duplicate
          photonHit('', 12, 47, { name: undefined, street: 'Hauptstrasse' }), // no name at all
        ]),
        { status: 200, headers: JSON_HEADERS },
      ),
  };
  const body = await (await call('/api/search/places?q=Wien&limit=3')).json();
  assert.equal(body.results.length, 3, 'limit is a hard cap');
  for (const place of body.results) {
    assert.ok(['swisstopo', 'photon'].includes(place.source));
    assert.ok(place.label.length > 0, 'no empty suggestion rows');
    assert.equal(typeof place.lat, 'number');
    assert.equal(typeof place.lon, 'number');
  }
  const deduped = await (await call('/api/search/places?q=Wien2&limit=20')).json();
  assert.equal(new Set(deduped.results.map((r) => r.label)).size, deduped.results.length, 'no duplicate rows');
});

test('/api/health names the place-search sources with their attribution', async () => {
  const body = await (await call('/api/health')).json();
  const ids = body.placeSources.map((s) => s.id);
  assert.deepEqual(ids, ['swisstopo', 'photon']);
  assert.equal(body.placeSources.find((s) => s.id === 'swisstopo').scope, 'Switzerland');
  assert.equal(body.placeSources.find((s) => s.id === 'photon').scope, 'worldwide');
  assert.match(body.placeSources.find((s) => s.id === 'photon').attribution, /OpenStreetMap/);
  assert.ok(body.upstreams.includes('photon.komoot.io'));
});

