/**
 * One honest sentence about what the list offers: places found, record matches,
 * or neither. Counts come from the suggestions that are really shown, and the
 * source names are the ones the Worker really used (swisstopo for Switzerland,
 * OpenStreetMap/Photon for the rest of the world) — a worldwide answer must not
 * be labelled “swisstopo”. The attribution is the licence requirement of both
 * geocoders, so it travels with the suggestions.
 */
function statusText(places, records, local, source = 'swisstopo', attribution = '') {
  if (places.length === 0 && !records && local.length === 0) return 'Kein Ort und kein Titeltreffer gefunden.';
  const parts = [];
  if (places.length > 0) parts.push(`${places.length} Ortsvorschläge (${source})`);
  else parts.push('Kein Ortsvorschlag');
  if (records) parts.push(`${records.origin} zu „${records.query}“`);
  else if (local.length > 0) parts.push(`${local.length} Titelvorschläge aus dem Bestand`);
  const credit = places.length > 0 && attribution ? ` Orte: ${attribution}.` : '';
  return `${parts.join(' · ')}. Mit ↓/↑ wählen, Enter bestätigen.${credit}`;
}

